        try:
            if isinstance(v, dict):
                for k in ("position", "pos", "loc", "location", "xy"):
                    if k in v:
                        return p(v.get(k), d)
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except:
            pass
        return d

    def sgn(x):
        return -1 if x < 0 else (1 if x > 0 else 0)

    def man(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def ok(d):
        nx, ny = me[0] + d[0], me[1] + d[1]
        return (nx, ny) not in obs

    def best_of(cands, target=None, avoid=None):
        best = [0, 0]
        score = None
        for d in cands:
            nx, ny = me[0] + d[0], me[1] + d[1]
            if (nx, ny) in obs:
                continue
            v = []
            if target is not None:
                v.append(man((nx, ny), target))
            if avoid is not None:
                v.append(man((nx, ny), avoid))
            v.extend([-d[0], -d[1]])
            t = tuple(v)
            if score is None or t < score:
                score = t
                best = [d[0], d[1]]
        return best

    me = p(observation.get("self_position") or observation.get("self") or observation.get("position"))
    opp = p(observation.get("opponent_position") or observation.get("enemy_position"), me)

    obs = set()
    for q in observation.get("obstacles") or observation.get("walls") or []:
        obs.add(p(q))

    res = []
    for q in observation.get("resources") or []:
        res.append(p(q))
    if not res:
        for q in observation.get("resource_positions") or []:
            res.append(p(q))

    terr = []
    for q in observation.get("territory") or observation.get("control_points") or []:
