    # Pursuit/evasion: if close, move toward; otherwise move away if threatened.
    d0 = man(me, opp)
    if d0 <= 2:
        d = step(me, opp)
        if (d[0] or d[1]) and ok(d):
            return d
        return best_of([(1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)], avoid=opp, target=me)
    if opp != me:
        away = step(opp, me)
        if (away[0] or away[1]) and ok(away):
            return away

    # Territory/control: drift toward nearest known territory-ish point, else patrol.
    if terr:
        t = min(terr, key=lambda r: (man(me, r), r[0], r[1]))
        d = step(me, t)
